from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Sw_version(EmssimCommand):
    def __init__(self, method="sw_version", timeout=60, rpc_connection_name='localRPC'):
        super(Sw_version, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Sw_version, self).on_new_data(**data)
        if "msg" in data:
            if (data["msg"] == "Build information"):
                self._ret["build_table"] = self.parse_table_with_unique_key_to_dictionary(data['table'], 'TYPE')

            elif (data["msg"] == "File stored at following path"):
                self._ret["file_path"] = data["path"]
        elif ("status" in data):
            self._ret["status"] = data["status"]
